sys_script_client.script:
function onLoad() {
    var cfg = {
        custody: {
            table: 'x_hsb11_mss_c_proc_mss_custody_task',
            targetValue: 'mss_custody',
            targetLabel: 'MSS Custody'
        },
        equity: {
            table: 'x_hsb11_hsbc_mss_t_trade_task',
            targetValue: 'cash_equity',
            targetLabel: 'Cash Equity'
        }
    };

    function applyTarget(appKey) {
        var c = cfg[appKey];
        if (!c) return;

        g_form.setValue('table', c.table);
        g_form.setReadOnly('table', true);

        g_form.clearOptions('u_target_app');
        g_form.addOption('u_target_app', c.targetValue, c.targetLabel);
        g_form.setValue('u_target_app', c.targetValue);
    }

    var ga = new GlideAjax('TaskPriorityCalc');
    ga.addParam('sysparm_name', 'getuserDepartment');
    ga.getXMLAnswer(function(response) {
        if (response === 'both') {
            g_form.setReadOnly('table', true);
            return;
        }
        applyTarget(response); // handles 'custody' or 'equity'
    });
}
